const pres = new pptxgen();
pres.layout = 'LAYOUT_WIDE';
pres.author = 'Codex';
pres.company = 'Engineering Strategy';
pres.subject = 'Programming language trends and strategy';
pres.title = 'Language Strategy 2025';
pres.lang = 'en-US';

const theme = {
  primary: '0F172A',
  secondary: '1D4ED8',
  accent: '6366F1',
  light: '93C5FD',
  bg: 'EEF2FF'
};

for (let i = 1; i <= 6; i += 1) {
  const num = String(i).padStart(2, '0');
  const { createSlide } = require(`./slide-${num}.js`);
  createSlide(pres, theme);
}

pres.writeFile({ fileName: '/app/output/final_deck.pptx' });
